{
  "name": "Keithley 2015数字万用表",
  "name_en": "Keithley 2015 Digital Multimeter",
  "manufacturer": "Keithley",
  "description": "这是一台台式数字万用表，可用于实验室中的电阻等电学参数测量，并支持通过计算机进行自动化读数与测量模式切换。适合电子测试、器件表征和常规电学实验。",
  "description_en": "This is a bench digital multimeter used in laboratories for measuring electrical quantities such as resistance, with support for computer-controlled automated readings and measurement mode switching. It is suitable for electronics testing, device characterization, and general electrical lab work.",
  "tag_hints": [
    "digital multimeter",
    "resistance measurement",
    "bench instrument",
    "automated electrical testing",
    "instrument control",
    "electronic characterization"
  ],
  "actions": [
    {
      "action_name": "auto-beep",
      "description": "使仪器发出蜂鸣提示音。",
      "description_en": "Make the instrument emit a beep."
    },
    {
      "action_name": "auto-resistance",
      "description": "按指定电阻测量方式执行一次电阻测量。",
      "description_en": "Perform a resistance measurement using the specified resistance mode."
    },
    {
      "action_name": "auto-setresistance",
      "description": "设置电阻测量方式。",
      "description_en": "Set the resistance measurement mode."
    },
    {
      "action_name": "auto-read",
      "description": "读取仪器当前测量值。",
      "description_en": "Read the instrument's current measurement value."
    },
    {
      "action_name": "auto-serialWrite",
      "description": "向仪器发送一条底层串行命令。",
      "description_en": "Send a low-level serial command to the instrument."
    },
    {
      "action_name": "auto-serialASK",
      "description": "向仪器发送一条底层查询命令并读取返回结果。",
      "description_en": "Send a low-level serial query to the instrument and read back the response."
    }
  ]
}

